<template><PlayerPageShell title="我的赛事" subtitle="仅展示当前选手可访问的赛事"><view v-if="events.length" class="list"><view v-for="event in events" :key="event.eventId" class="card" @click="select(event)"><text class="name">{{ event.eventName }}</text><text class="status">{{ statusText(event.registrationStatus) }}</text></view></view><view v-else class="card muted">暂无可访问赛事</view></PlayerPageShell></template>
<script>import { getCurrentPlayer } from '@/api/competition-player';import PlayerPageShell from './components/PlayerPageShell.vue';import { guardCompetitionPlayerRoute } from '@/utils/competition-route-guard';import { useCompetitionPlayerStore } from '@/store/competitionPlayer';export default{components:{PlayerPageShell},data:()=>({events:[]}),async onShow(){if(!guardCompetitionPlayerRoute())return;try{const store=useCompetitionPlayerStore();store.setProfile(await getCurrentPlayer());this.events=store.events}catch(e){uni.showToast({title:e.message||'赛事加载失败',icon:'none'})}},methods:{select(event){useCompetitionPlayerStore().setCurrentEvent(event);uni.navigateBack()},statusText(status){return status==='eligible_activated'?'已激活':status||'资格处理中'}}}</script>
<style scoped>.list{display:flex;flex-direction:column;gap:20rpx}.card{display:flex;justify-content:space-between;align-items:center;padding:30rpx;background:#fff;border-radius:20rpx}.name{font-size:30rpx;font-weight:700}.status{font-size:24rpx;color:#1765df}.muted{justify-content:center;color:#8391a7}</style>
